  /* ---------- 출퇴근 찍기 (매장 기기에서 알바생이 이름 → 비밀번호) ---------- */
  var PUNCH_MAX_MIN = 16 * 60;   // 출근 후 이 시간 안에 찍으면 '퇴근', 넘으면 퇴근을 안 찍은 것으로 보고 새 '출근'

