    rows.push([S('band', '표준 급여명세서 (임금명세서)')].concat(fill(3, 'band')));
    rows.push([S('sub', '근로기준법 제48조 제2항 · 같은 법 시행령 제27조의2 기재사항 기준')].concat(fill(3, 'sub')));
