      var isSat = d.dayIndex === 5, isSun = d.dayIndex === 6;
      var dateStyle = off ? 'cOff' : (isSun ? 'cSun' : (isSat ? 'cSat' : 'cText'));
      var meal = r.includeMeal && d.mealEligible;
      var note = '';
      if (off) note = '휴무';
